import 'package:flutter/material.dart';
import 'database_service.dart';
import 'main.dart';
class ProgressScreen extends StatefulWidget{const ProgressScreen({super.key});@override State<ProgressScreen> createState()=>_ProgressScreenState();}
class _ProgressScreenState extends State<ProgressScreen>{Map<String,int> stats={};List<Map<String,Object?>> attempts=[];bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{final s=await DatabaseService.instance.stats();final a=await DatabaseService.instance.recentAttempts();if(mounted)setState((){stats=s;attempts=a;loading=false;});}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Meu progresso'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(18),children:[const Text('Seu desempenho',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:14),Card(child:ListTile(leading:const Icon(Icons.task_alt,color:lime),title:const Text('Questões respondidas'),trailing:Text('${stats['answered']??0}'))),Card(child:ListTile(leading:const Icon(Icons.check_circle,color:Colors.greenAccent),title:const Text('Respostas corretas'),trailing:Text('${stats['correct']??0}'))),Card(child:ListTile(leading:const Icon(Icons.quiz,color:lime),title:const Text('Simulados concluídos'),trailing:Text('${stats['sessions']??0}'))),Card(child:ListTile(leading:const Icon(Icons.star,color:lime),title:const Text('Questões favoritas'),trailing:Text('${stats['favorites']??0}'))),const SizedBox(height:18),const Text('Histórico recente',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),if(attempts.isEmpty)const Padding(padding:EdgeInsets.all(14),child:Text('Ainda não há respostas registradas.')),...attempts.map((a)=>Card(child:ListTile(leading:Icon((a['correct'] as int? ??0)==1?Icons.check_circle:Icons.cancel,color:(a['correct'] as int? ??0)==1?Colors.greenAccent:Colors.orangeAccent),title:Text('${a['prompt']??'Questão indisponível'}',maxLines:2,overflow:TextOverflow.ellipsis),subtitle:Text('Sua resposta: ${a['chosen']} • ${a['createdAt']}'))))]));}
}
